import { Sparkles } from 'lucide-react';

/** Shown wherever model output is, so it never passes for a person's or a checked fact. */
export const AI_NOTICE = 'Written by AI models, which can be wrong. Check anything important.';

/**
 * Says that the text beside it was generated by AI (EU AI Act art. 50 transparency):
 * shared by chat and run results, never reworded per screen (AGENTS.md §3).
 */
export function AiNotice({ className = '' }: { className?: string }) {
  return (
    <p className={`flex items-center gap-1.5 text-xs text-slate-400 ${className}`}>
      <Sparkles aria-hidden="true" className="size-3.5 shrink-0" />
      {AI_NOTICE}
    </p>
  );
}
